{
  "name": "@vkontakte/api-schema",
  "version": "5.199.99",
  "description": "VK API JSON Schema",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/VKCOM/vk-api-schema.git"
  },
  "keywords": [
    "vk",
    "vkontakte",
    "vkapi",
    "vk-api",
    "vkontakte-api",
    "vk-api-schema"
  ],
  "author": "https://vk.com/dev",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/VKCOM/vk-api-schema/issues"
  },
  "homepage": "https://github.com/VKCOM/vk-api-schema#readme",
  "scripts": {
    "release": "./tasks/release.sh",
    "test": "npx @vkontakte/api-schema-typescript-generator --schemaDir . --methods '*'"
  }
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - objects",
  "description": "Contains JSON Schema documents explaining the VK.COM API - objects",
  "termsOfService": "https://dev.vk.com/rules",
  "definitions": {
    "oauth_error": {
      "type": "object",
      "properties": {
        "error": {
          "type": "string",
          "description": "Error type",
          "required": true
        },
        "error_description": {
          "type": "string",
          "description": "Error description",
          "required": true
        },
        "redirect_uri": {
          "type": "string",
          "description": "URI for validation"
        }
      }
    }
  }
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - methods",
  "description": "Contains JSON Schema documents explaining the VK.COM API - methods",
  "termsOfService": "https://dev.vk.com/rules",
  "methods": [
    {
      "name": "auth.restore",
      "description": "Allows to restore account access using a code received via SMS. \" This method is only available for apps with [vk.com/dev/auth_direct|Direct authorization] access. \"",
      "access_token_type": [
        "user",
        "open",
        "service"
      ],
      "parameters": [
        {
          "name": "phone",
          "description": "User phone number.",
          "type": "string",
          "required": true
        },
        {
          "name": "last_name",
          "description": "User last name.",
          "type": "string",
          "required": true
        }
      ],
      "responses": {
        "response": {
          "$ref": "../auth/responses.json#/definitions/auth_restore_response"
        }
      },
      "errors": [
        {
          "$ref": "../errors.json#/errors/api_error_auth_flood_error"
        }
      ]
    }
  ]
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - responses",
  "description": "Contains JSON Schema documents explaining the VK.COM API - responses",
  "termsOfService": "https://dev.vk.com/rules",
  "definitions": {
    "auth_restore_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "object",
          "properties": {
            "success": {
              "type": "integer",
              "description": "1 if success",
              "enum": [
                1
              ],
              "enumNames": [
                "ok"
              ]
            },
            "sid": {
              "type": "string",
              "description": "Parameter needed to grant access by code"
            }
          },
          "required": true
        }
      }
    }
  }
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - methods",
  "description": "Contains JSON Schema documents explaining the VK.COM API - methods",
  "termsOfService": "https://dev.vk.com/rules",
  "methods": [
    {
      "name": "search.getHints",
      "description": "Allows the programmer to do a quick search for any substring.",
      "access_token_type": [
        "user"
      ],
      "parameters": [
        {
          "name": "q",
          "description": "Search query string.",
          "type": "string",
          "maxLength": 9000
        },
        {
          "name": "offset",
          "description": "Offset for querying specific result subset",
          "type": "integer",
          "minimum": 0,
          "maximum": 200
        },
        {
          "name": "limit",
          "description": "Maximum number of results to return.",
          "type": "integer",
          "default": 9,
          "minimum": 0,
          "maximum": 200
        },
        {
          "name": "filters",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "name": "fields",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "name": "search_global",
          "type": "boolean",
          "default": true
        }
      ],
      "responses": {
        "response": {
          "$ref": "../search/responses.json#/definitions/search_getHints_response"
        }
      }
    }
  ]
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - responses",
  "description": "Contains JSON Schema documents explaining the VK.COM API - responses",
  "termsOfService": "https://dev.vk.com/rules",
  "definitions": {
    "search_getHints_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "object",
          "properties": {
            "count": {
              "type": "integer",
              "minimum": 0,
              "required": true
            },
            "items": {
              "type": "array",
              "items": {
                "$ref": "../search/objects.json#/definitions/search_hint"
              },
              "required": true
            },
            "suggested_queries": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          },
          "required": true
        }
      }
    }
  }
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - objects",
  "description": "Contains JSON Schema documents explaining the VK.COM API - objects",
  "termsOfService": "https://dev.vk.com/rules",
  "definitions": {
    "search_hint": {
      "type": "object",
      "properties": {
        "app": {
          "$ref": "../apps/objects.json#/definitions/apps_app"
        },
        "description": {
          "type": "string",
          "description": "Object description",
          "required": true
        },
        "global": {
          "description": "Information whether the object has been found globally",
          "$ref": "../base/objects.json#/definitions/base_bool_int"
        },
        "group": {
          "$ref": "../groups/objects.json#/definitions/groups_group"
        },
        "profile": {
          "$ref": "../users/objects.json#/definitions/users_user_min"
        },
        "section": {
          "$ref": "../search/objects.json#/definitions/search_hint_section"
        },
        "type": {
          "$ref": "../search/objects.json#/definitions/search_hint_type",
          "required": true
        },
        "link": {
          "$ref": "../base/objects.json#/definitions/base_link"
        }
      }
    },
    "search_hint_section": {
      "type": "string",
      "description": "Section title",
      "enum": [
        "groups",
        "events",
        "publics",
        "correspondents",
        "people",
        "friends",
        "mutual_friends",
        "promo"
      ]
    },
    "search_hint_type": {
      "type": "string",
      "description": "Object type",
      "enum": [
        "group",
        "profile",
        "vk_app",
        "app",
        "html5_game",
        "link"
      ]
    }
  }
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - objects",
  "description": "Contains JSON Schema documents explaining the VK.COM API - objects",
  "termsOfService": "https://dev.vk.com/rules",
  "definitions": {
    "docs_doc": {
      "type": "object",
      "properties": {
        "id": {
          "type": "integer",
          "description": "Document ID",
          "minimum": 0,
          "required": true
        },
        "owner_id": {
          "type": "integer",
          "description": "Document owner ID",
          "entity": "owner",
          "format": "int64",
          "required": true
        },
        "title": {
          "type": "string",
          "description": "Document title",
          "required": true
        },
        "size": {
          "type": "integer",
          "description": "File size in bites",
          "minimum": 0,
          "required": true
        },
        "ext": {
          "type": "string",
          "description": "File extension",
          "required": true
        },
        "url": {
          "type": "string",
          "format": "uri",
          "description": "File URL"
        },
        "date": {
          "type": "integer",
          "description": "Date when file has been uploaded in Unixtime",
          "minimum": 0,
          "required": true
        },
        "type": {
          "type": "integer",
          "description": "Document type",
          "required": true
        },
        "preview": {
          "$ref": "../docs/objects.json#/definitions/docs_doc_preview"
        },
        "is_licensed": {
          "$ref": "../base/objects.json#/definitions/base_bool_int"
        },
        "access_key": {
          "type": "string",
          "description": "Access key for the document"
        },
        "tags": {
          "type": "array",
          "description": "Document tags",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "docs_doc_attachment_type": {
      "type": "string",
      "description": "Doc attachment type",
      "enum": [
        "doc",
        "graffiti",
        "audio_message"
      ]
    },
    "docs_doc_preview": {
      "type": "object",
      "properties": {
        "audio_msg": {
          "$ref": "../docs/objects.json#/definitions/docs_doc_preview_audio_msg"
        },
        "graffiti": {
          "$ref": "../docs/objects.json#/definitions/docs_doc_preview_graffiti"
        },
        "photo": {
          "$ref": "../docs/objects.json#/definitions/docs_doc_preview_photo"
        },
        "video": {
          "$ref": "../docs/objects.json#/definitions/docs_doc_preview_video"
        }
      }
    },
    "docs_doc_preview_audio_msg": {
      "type": "object",
      "properties": {
        "duration": {
          "type": "integer",
          "description": "Audio message duration in seconds",
          "minimum": 0,
          "required": true
        },
        "link_mp3": {
          "type": "string",
          "format": "uri",
          "description": "MP3 file URL",
          "required": true
        },
        "link_ogg": {
          "type": "string",
          "format": "uri",
          "description": "OGG file URL",
          "required": true
        },
        "waveform": {
          "type": "array",
          "items": {
            "type": "integer",
            "description": "Sound visualisation",
            "minimum": 0
          },
          "required": true
        }
      }
    },
    "docs_doc_preview_graffiti": {
      "type": "object",
      "properties": {
        "src": {
          "type": "string",
          "format": "uri",
          "description": "Graffiti file URL",
          "required": true
        },
        "width": {
          "type": "integer",
          "description": "Graffiti width",
          "minimum": 0,
          "required": true
        },
        "height": {
          "type": "integer",
          "description": "Graffiti height",
          "minimum": 0,
          "required": true
        }
      }
    },
    "docs_doc_preview_photo": {
      "type": "object",
      "properties": {
        "sizes": {
          "type": "array",
          "items": {
            "$ref": "../docs/objects.json#/definitions/docs_doc_preview_photo_sizes"
          }
        }
      }
    },
    "docs_doc_preview_photo_sizes": {
      "type": "object",
      "properties": {
        "src": {
          "type": "string",
          "format": "uri",
          "description": "URL of the image",
          "required": true
        },
        "width": {
          "type": "integer",
          "description": "Width in px",
          "minimum": 0,
          "required": true
        },
        "height": {
          "type": "integer",
          "description": "Height in px",
          "minimum": 0,
          "required": true
        },
        "type": {
          "$ref": "../photos/objects.json#/definitions/photos_photo_sizes_type",
          "required": true
        }
      }
    },
    "docs_doc_preview_video": {
      "type": "object",
      "properties": {
        "src": {
          "type": "string",
          "format": "uri",
          "description": "Video URL",
          "required": true
        },
        "width": {
          "type": "integer",
          "description": "Video's width in pixels",
          "minimum": 0,
          "required": true
        },
        "height": {
          "type": "integer",
          "description": "Video's height in pixels",
          "minimum": 0,
          "required": true
        },
        "file_size": {
          "type": "integer",
          "description": "Video file size in bites",
          "minimum": 0,
          "required": true
        }
      }
    },
    "docs_doc_types": {
      "type": "object",
      "properties": {
        "id": {
          "type": "integer",
          "description": "Doc type ID",
          "required": true
        },
        "name": {
          "type": "string",
          "description": "Doc type title",
          "required": true
        },
        "count": {
          "type": "integer",
          "minimum": 0,
          "description": "Number of docs",
          "required": true
        }
      }
    }
  }
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - responses",
  "description": "Contains JSON Schema documents explaining the VK.COM API - responses",
  "termsOfService": "https://dev.vk.com/rules",
  "definitions": {
    "docs_add_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "integer",
          "description": "Document ID",
          "required": true
        }
      }
    },
    "docs_doc_upload_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "object",
          "properties": {
            "file": {
              "type": "string",
              "description": "Uploaded file data"
            }
          },
          "required": true
        }
      }
    },
    "docs_getById_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "array",
          "items": {
            "$ref": "../docs/objects.json#/definitions/docs_doc"
          },
          "required": true
        }
      }
    },
    "docs_getTypes_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "object",
          "properties": {
            "count": {
              "type": "integer",
              "description": "Total number",
              "required": true
            },
            "items": {
              "type": "array",
              "items": {
                "$ref": "../docs/objects.json#/definitions/docs_doc_types"
              },
              "required": true
            }
          },
          "required": true
        }
      }
    },
    "docs_getUploadServer_response": {
      "type": "object",
      "properties": {
        "response": {
          "$ref": "../base/objects.json#/definitions/base_upload_server",
          "required": true
        }
      }
    },
    "docs_get_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "object",
          "properties": {
            "count": {
              "type": "integer",
              "description": "Total number",
              "required": true
            },
            "items": {
              "type": "array",
              "items": {
                "$ref": "../docs/objects.json#/definitions/docs_doc"
              },
              "required": true
            }
          },
          "required": true
        }
      }
    },
    "docs_save_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "object",
          "properties": {
            "type": {
              "$ref": "../docs/objects.json#/definitions/docs_doc_attachment_type"
            },
            "audio_message": {
              "$ref": "../messages/objects.json#/definitions/messages_audio_message"
            },
            "doc": {
              "$ref": "../docs/objects.json#/definitions/docs_doc"
            },
            "graffiti": {
              "$ref": "../messages/objects.json#/definitions/messages_graffiti"
            }
          },
          "required": true
        }
      }
    },
    "docs_search_response": {
      "type": "object",
      "properties": {
        "response": {
          "type": "object",
          "properties": {
            "count": {
              "type": "integer",
              "description": "Total number",
              "required": true
            },
            "items": {
              "type": "array",
              "items": {
                "$ref": "../docs/objects.json#/definitions/docs_doc"
              },
              "required": true
            }
          },
          "required": true
        }
      }
    }
  }
}

{
  "$schema": "../schema.json",
  "version": "5.199",
  "title": "VK API JSON Schema - methods",
  "description": "Contains JSON Schema documents explaining the VK.COM API - methods",
  "termsOfService": "https://dev.vk.com/rules",
  "methods": [
    {
      "name": "docs.add",
      "description": "Copies a document to a user's or community's document list.",
      "access_token_type": [
        "user"
      ],
      "parameters": [
        {
          "name": "owner_id",
          "description": "ID of the user or community that owns the document. Use a negative value to designate a community ID.",
          "type": "integer",
          "required": true,
          "format": "int64",
          "entity": "owner"
        },
        {
          "name": "doc_id",
          "description": "Document ID.",
          "type": "integer",
          "required": true,
          "minimum": 0
        },
        {
          "name": "access_key",
          "description": "Access key. This parameter is required if 'access_key' was returned with the document's data.",
          "type": "string"
        }
      ],
      "responses": {
        "response": {
          "$ref": "../docs/responses.json#/definitions/docs_add_response"
        }
      }
    },
    {
      "name": "docs.delete",
      "description": "Deletes a user or community document.",
      "access_token_type": [
        "user"
      ],
      "parameters": [
        {
          "name": "owner_id",
          "description": "ID of the user or community that owns the document. Use a negative value to designate a community ID.",
          "type": "integer",
          "required": true,
          "format": "int64",
          "entity": "owner"
        },
        {
          "name": "doc_id",
          "description": "Document ID.",
          "type": "integer",
          "required": true,
          "minimum": 0
        }
      ],
      "responses": {
        "response": {
          "$ref": "../base/responses.json#/definitions/base_ok_response"
        }
      },
      "errors": [
        {
          "$ref": "../errors.json#/errors/api_error_param_doc_delete_access"
        },
        {
          "$ref": "../errors.json#/errors/api_error_param_doc_id"
        }
      ]
    },
    {
      "name": "docs.edit",
      "description": "Edits a document.",
      "access_token_type": [
        "user"
      ],
      "parameters": [
        {
          "name": "owner_id",
          "description": "User ID or community ID. Use a negative value to designate a community ID.",
          "type": "integer",
          "format": "int64",
          "entity": "owner"
        },
        {
          "name": "doc_id",
          "description": "Document ID.",
          "type": "integer",
          "required": true,
          "minimum": 0
        },
        {
          "name": "title",
          "description": "Document title.",
          "type": "string",
          "required": true,
          "maxLength": 128
        },
        {
          "name": "tags",
          "description": "Document tags.",
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      ],
      "responses": {
        "response": {
          "$ref": "../base/responses.json#/definitions/base_ok_response"
        }
      },
      "errors": [
        {
          "$ref": "../errors.json#/errors/api_error_param_doc_access"
        },
        {
          "$ref": "../errors.json#/errors/api_error_param_doc_id"
        },
        {
          "$ref": "../errors.json#/errors/api_error_param_doc_title"
        }
      ]
    },
    {
      "name": "docs.get",
      "description": "Returns detailed information about user or community documents.",
      "access_token_type": [
        "user"
      ],
      "parameters": [
        {
          "name": "count",
          "description": "Number of documents to return. By default, all documents.",
          "type": "integer",
          "minimum": 0
        },
        {
          "name": "offset",
          "description": "Offset needed to return a specific subset of documents.",
          "type": "integer",
          "minimum": 0
        },
        {
          "name": "type",
          "type": "integer",
          "default": 0,
          "minimum": 0,
          "enum": [
            0,
            1,
            2,
            3,
            4,
            5,
            6,
            7,
            8
          ],
          "enumNames": [
            "all",
            "text",
            "archive",
            "gif",
            "image",
            "audio",
            "video",
            "ebook",
            "default"
          ]
        },
        {
          "name": "owner_id",
          "description": "ID of the user or community that owns the documents. Use a negative value to designate a community ID.",
          "type": "integer",
          "format": "int64",
          "entity": "owner"
        },
        {
          "name": "return_tags",
          "type": "boolean",
          "default": false
        }
      ],
      "responses": {
        "response": {
          "$ref": "../docs/responses.json#/definitions/docs_get_response"
        }
      }
    },
    {
      "name": "docs.getById",
      "description": "Returns information about documents by their IDs.",
      "access_token_type": [
        "user",
        "group"
      ],
      "parameters": [
        {
          "name": "docs",
          "description": "Document IDs. Example: , \"66748_91488,66748_91455\",",
          "type": "array",
          "required": true,
          "items": {
            "type": "string"
          }
        },
        {
          "name": "return_tags",
          "type": "boolean",
          "default": false
        }
      ],
      "responses": {
        "response": {
          "$ref": "../docs/responses.json#/definitions/docs_getById_response"
        }
      }
    },
    {
      "name": "docs.getMessagesUploadServer",
      "description": "Returns the server address for document upload.",
      "access_token_type": [
        "user",
        "group"
      ],
      "parameters": [
        {
          "name": "type",
          "description": "Document type.",
          "type": "string",
          "default": "doc",
          "enum": [
            "audio_message",
            "doc",
            "graffiti"
          ]
        },
        {
          "name": "peer_id",
          "description": "Destination ID. \"For user: 'User ID', e.g. '12345'. For chat: '2000000000' + 'Chat ID', e.g. '2000000001'. For community: '- Community ID', e.g. '-12345'. \"",
          "type": "integer",
          "format": "int32"
        }
      ],
      "responses": {
        "response": {
          "$ref": "../docs/responses.json#/definitions/docs_getUploadServer_response"
        }
      },
      "errors": [
        {
          "$ref": "../errors.json#/errors/api_error_messages_deny_send"
        }
      ]
    },
    {
      "name": "docs.getTypes",
      "description": "Returns documents types available for current user.",
      "access_token_type": [
        "user"
      ],
      "parameters": [
        {
          "name": "owner_id",
